import { ChevronRight } from 'lucide-react'
import { Fragment, type ReactNode } from 'react'

import { cx } from '~/lib/cx'
import styles from './breadcrumb.module.scss'

export type BreadcrumbItem = {
  label: string
  href?: string
  current?: boolean
}

export interface BreadcrumbProps {
  items: BreadcrumbItem[]
  className?: string
  separator?: ReactNode
}

/** Compact path navigation. The final item is marked as the current page. */
export function Breadcrumb({ items, className, separator }: BreadcrumbProps) {
  return (
    <nav
      aria-label="Breadcrumb"
      className={cx(styles.root, className)}
    >
      <ol className={styles.list}>
        {items.map((item, index) => (
          <Fragment key={`${item.label}-${index}`}>
            {index > 0 ? (
              <li aria-hidden className={styles.separator}>
                {separator ?? <ChevronRight aria-hidden />}
              </li>
            ) : null}
            <li className={styles.item}>
              {item.href && !item.current ? (
                <a href={item.href} className={styles.link}>
                  {item.label}
                </a>
              ) : (
                <span
                  aria-current={item.current ? 'page' : undefined}
                  className={cx(styles.label, item.current && styles.current)}
                >
                  {item.label}
                </span>
              )}
            </li>
          </Fragment>
        ))}
      </ol>
    </nav>
  )
}

@use 'styles' as vz;

.root {
  width: 100%;
  overflow-x: auto;

  @include vz.scrollbar(6px);
}

.list {
  display: flex;
  align-items: center;
  gap: vz.space(1.5);
  min-width: max-content;
  margin: 0;
  padding: 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');
  list-style: none;
}

.item {
  display: inline-flex;
  align-items: center;
}

.separator {
  display: inline-flex;
  align-items: center;
  color: vz.color('muted-foreground', 0.7);

  svg {
    @include vz.icon(3.5);
  }
}

.label {
  color: inherit;
}

.current {
  color: vz.color('foreground');
  font-weight: 500;
}

.link {
  border-radius: vz.radius('xs');
  color: inherit;
  text-decoration: none;
  transition: color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    color: vz.color('foreground');
  }

  @include vz.focus-ring(2px, 2px, 0.6);
}
